step.script:
env HOME=/tmp bash -lc 'set -eu; CITY_SLUG="$(printf "%s" "Almeria" | tr "[:upper:]" "[:lower:]")"; docker run --rm -v /home/ubuntu/data_storage:/src_data:ro -v /home/ubuntu/work/frontend_build/test_frontend:/repo alpine:3.20 sh -lc " set -eu; SRC_DIR=\"\"; for d in /src_data/*; do
  [ -d \"\$d\" ] || continue;
  if [ \"\$(basename \"\$d\" | tr \"[:upper:]\" \"[:lower:]\")\" = \"$CITY_SLUG\" ]; then
    SRC_DIR=\"\$d\";
    break;
  fi;
done; if [ -z \"\$SRC_DIR\" ]; then
  echo \"City data folder not found in /home/ubuntu/data_storage for Almeria\";
  exit 1;
fi; SRC_FILE=\"\$SRC_DIR/00_master/master_events.json\"; DEST_FILE=\"/repo/data/$CITY_SLUG/master_events.json\"; [ -f \"\$SRC_FILE\" ] || { echo \"Missing source file: \$SRC_FILE\"; exit 1; }; mkdir -p \"\$(dirname \"\$DEST_FILE\")\"; cp \"\$SRC_FILE\" \"\$DEST_FILE\"; echo \"Snapshot copied to \$DEST_FILE\" "'

env HOME=/tmp bash -lc 'set -eu; CITY_SLUG="$(printf "%s" "Almeria" | tr "[:upper:]" "[:lower:]")"; SNAPSHOT_PATH="data/$CITY_SLUG/master_events.json"; docker run --rm --entrypoint sh -v /home/ubuntu/work/frontend_build/test_frontend:/repo -v /home/ubuntu/.ssh:/root/.ssh:ro -w /repo alpine/git:latest -lc " set -eu; git config --global --add safe.directory /repo; git add \"$SNAPSHOT_PATH\"; if git diff --cached --quiet -- \"$SNAPSHOT_PATH\"; then
  echo \"No snapshot changes to commit for $SNAPSHOT_PATH\";
  exit 0;
fi; BRANCH=\$(git rev-parse --abbrev-ref HEAD); COMMIT_MSG=\"chore(snapshot): update master_events for $CITY_SLUG \$(date -u +%Y-%m-%dT%H:%M:%SZ)\"; git -c user.name=\"Dagu Snapshot Bot\" -c user.email=\"dagu-snapshot@example.com\" commit -m \"\$COMMIT_MSG\" -- \"$SNAPSHOT_PATH\"; git push origin \"\$BRANCH\" "'

env HOME=/tmp bash -lc 'set -eu; IMAGE="infra_scripts-test_frontend_build:latest"; if ! docker image inspect "$IMAGE" >/dev/null 2>&1; then
  echo "Missing image: $IMAGE";
  echo "Build it first with: docker compose --profile build build test_frontend_build";
  exit 1;
fi; EXTRA_ARGS=""; if [ "1" = "1" ]; then
  EXTRA_ARGS="--no-download-images";
fi; docker run --rm --entrypoint sh -e ORBITA_CITY="Almeria" -v /home/ubuntu/work/frontend_build/test_frontend:/app -v infra_scripts_test_frontend_node_modules:/app/node_modules -v /home/ubuntu/work/frontend_build/test_frontend/dist:/app/dist -v /home/ubuntu/data_storage:/home/ubuntu/data_storage "$IMAGE" scripts/docker_static_entrypoint.sh --city "Almeria" --out "dist" --base-url "https://orbitatest.b-cdn.net/" $EXTRA_ARGS'

env HOME=/tmp bash -lc 'set -eu; echo "[upload_to_bunny] USER: $(whoami)"; echo "[upload_to_bunny] PWD: $(pwd)"; echo "[upload_to_bunny] ENV HOME: $HOME"; echo "[upload_to_bunny] TARGET_CITY: Almeria"; CITY_SLUG="$(printf "%s" "Almeria" | tr "[:upper:]" "[:lower:]")"; echo "[upload_to_bunny] CITY_SLUG: $CITY_SLUG"; echo "[upload_to_bunny] BUNNY_STORAGE_API_KEY: a5ebdb10-e74d-45d6-8934617053f9-5f56-4b14"; DIST_PATH="/dist/$CITY_SLUG"; echo "[upload_to_bunny] DIST_PATH: $DIST_PATH"; echo "[upload_to_bunny] Check dir: $DIST_PATH"; if [ -d "$DIST_PATH" ]; then
  echo "[upload_to_bunny] Directory exists: $DIST_PATH";
else
  echo "[upload_to_bunny] Directory missing: $DIST_PATH";
  ls -l "/dist"
  exit 1;
fi; docker run --rm --entrypoint sh -e BUNNY_STORAGE_ZONE="orbitastorage" -e BUNNY_STORAGE_API_KEY="a5ebdb10-e74d-45d6-8934617053f9-5f56-4b14" -e CITY_SLUG="$CITY_SLUG" -v /home/ubuntu/work/frontend_build/test_frontend/dist:/dist infra_scripts-test_frontend:latest -lc " set -eu; cd /dist/\$CITY_SLUG; lftp -u \"\orbitastorage,\a5ebdb10-e74d-45d6-8934617053f9-5f56-4b14\" storage.bunnycdn.com -e \" cd \$CITY_SLUG; mirror -R --delete --parallel=25 . .; bye \" "'
